gboolean handle_file_transfer_initiation(gpointer data, gint fd, b_input_condition cond) {
    Transfer *transfer = (Transfer *)data;
    Connection *conn = transfer_get_connection(transfer);
    Buddy *buddy = connection_get_buddy(conn);

    if (!buddy || !transfer_start(transfer, buddy)) {
        return FALSE;
    }

    transfer_set_callbacks(transfer);
    transfer_associate_data(transfer, data);

    return TRUE;
}

gboolean handle_new_file_transfer(gpointer data, gint fd, b_input_condition cond) {
    TransferData *transfer_data = (TransferData *)data;
    Connection *conn = transfer_data->connection;
    Buddy *buddy = find_buddy_by_handle(conn, transfer_data->buddy_handle);

    if (!buddy) {
        return FALSE;
    }

    FileTransfer *file_transfer = create_file_transfer(conn, buddy, transfer_data->file_info);
    if (!file_transfer) {
        return FALSE;
    }

    transfer_data->file_transfer = file_transfer;
    setup_transfer_callbacks(file_transfer);

    return TRUE;
}
